Q.append(q(f"{p}2019_{n:02d}",2019,a,d,"O Deep Ecology, desenvolvido por Arne Næss, propõe reformulação radical da relação entre seres humanos e natureza. Essa abordagem filosófica influencia movimentos ambientalistas ao redor do mundo.","O Deep Ecology propõe:",["Manter relação atual entre seres humanos e natureza","Reformulação radical da relação entre seres humanos e natureza","Apenas proteger biodiversidade","Apenas gerar lucro","Não tem impacto na sociedade"],"B",3,35));n+=1
