Q.append(q(f"{p}2019_{n:02d}",2019,a,d,"As energias renováveis, como solar e eólica, têm ganhado espaço na matriz energética brasileira. São consideradas mais limpas porque não emitem poluentes durante operação.","Uma vantagem das energias renováveis é:",["São mais baratas que todas as outras fontes","Não emitem poluentes durante sua operação","Podem ser utilizadas em qualquer lugar","Não dependem de condições climáticas","Substituem completamente fontes fósseis"],"B",1,78));n+=1
